import{_ as r,r as t,o,c as s,e as n,a as d,s as l}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Widgets - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Generic Widgets","slug":"generic-widgets","link":"#generic-widgets","children":[{"level":3,"title":"Class definition","slug":"class-definition","link":"#class-definition","children":[]},{"level":3,"title":"AJAX handlers","slug":"ajax-handlers","link":"#ajax-handlers","children":[]},{"level":3,"title":"Binding widgets to controllers","slug":"binding-widgets-to-controllers","link":"#binding-widgets-to-controllers","children":[]}]},{"level":2,"title":"Form Widgets","slug":"form-widgets","link":"#form-widgets","children":[{"level":3,"title":"Class definition","slug":"class-definition-1","link":"#class-definition-1","children":[]},{"level":3,"title":"Form widget properties","slug":"form-widget-properties","link":"#form-widget-properties","children":[]},{"level":3,"title":"Form widget registration","slug":"form-widget-registration","link":"#form-widget-registration","children":[]},{"level":3,"title":"Loading form data","slug":"loading-form-data","link":"#loading-form-data","children":[]},{"level":3,"title":"Saving form data","slug":"saving-form-data","link":"#saving-form-data","children":[]}]},{"level":2,"title":"Report Widgets","slug":"report-widgets","link":"#report-widgets","children":[{"level":3,"title":"Report widget classes","slug":"report-widget-classes","link":"#report-widget-classes","children":[]},{"level":3,"title":"Report widget properties","slug":"report-widget-properties","link":"#report-widget-properties","children":[]},{"level":3,"title":"Report widget registration","slug":"report-widget-registration","link":"#report-widget-registration","children":[]}]}],"relativePath":"1.x/backend/widgets.md","filePath":"1.x/backend/widgets.md"}'),g={name:"1.x/backend/widgets.md"};function c(p,e,h,u,m,f){const i=t("pre-heading"),a=t("post-heading");return o(),s("div",null,[n(i),e[0]||(e[0]=d("h1",null,"Widgets",-1)),n(a),e[1]||(e[1]=l(`<p>Widgets are self-contained blocks of functionality that solve different tasks. Widgets always have a user interface and a back-end controller (the widget class) that prepares the widget data and handles AJAX requests generated by the widget user interface.</p><h2 id="generic-widgets"><a href="#generic-widgets" class="header-anchor">#</a> Generic Widgets</h2><p>Widgets are the back-end equivalent of front-end <a href="./../cms/components.html">Components</a>. They are similar because they are modular bundles of functionality, supply partials and are named using aliases. The key difference is that back-end widgets use YAML markup for their configuration and bind themselves to Backend pages.</p><p>Widget classes reside inside the <strong>widgets</strong> directory of the plugin directory. The directory name matches the name of the widget class written in lowercase. Widgets can supply assets and partials. An example widget directory structure looks like this:</p><pre><code>widgets/
  /form
    /partials
      _form.htm     &lt;=== Widget partial file
    /assets
      /js
        form.js     &lt;=== Widget JavaScript file
      /css
        form.css    &lt;=== Widget StyleSheet file
  Form.php          &lt;=== Widget class
</code></pre><h3 id="class-definition"><a href="#class-definition" class="header-anchor">#</a> Class definition</h3><p>The generic widget classes must extend the <code>Backend\\Classes\\WidgetBase</code> class. As any other plugin class, generic widget controllers should belong to the <a href="./../plugin/registration.html#plugin-namespaces">plugin namespace</a>. Example widget controller class definition:</p><pre><code>&lt;?php namespace Backend\\Widgets;

use Backend\\Classes\\WidgetBase;

class Lists extends WidgetBase
{
    /**
     * @var string A unique alias to identify this widget.
     */
    protected $defaultAlias = &#39;list&#39;;

    // ...
}
</code></pre><p>The widget class must contain a <strong>render()</strong> method for producing the widget markup by rendering a widget partial. Example:</p><pre><code>public function render()
{
    return $this-&gt;makePartial(&#39;list&#39;);
}
</code></pre><p>To pass variables to partials you can either add them to the <code>$vars</code> property.</p><pre><code>public function render()
{
    $this-&gt;vars[&#39;var&#39;] = &#39;value&#39;;

    return $this-&gt;makePartial(&#39;list&#39;);
}
</code></pre><p>Alternatively you may pass the variables to the second parameter of the makePartial() method:</p><pre><code>public function render()
{
    return $this-&gt;makePartial(&#39;list&#39;, [&#39;var&#39; =&gt; &#39;value&#39;]);
}
</code></pre><h3 id="ajax-handlers"><a href="#ajax-handlers" class="header-anchor">#</a> AJAX handlers</h3><p>Widgets implement the same AJAX approach as the <a href="./controllers-ajax.html#ajax">back-end controllers</a>. The AJAX handlers are public methods of the widget class with names starting with the <strong>on</strong> prefix. The only difference between the widget AJAX handlers and backend controller&#39;s AJAX handlers is that you should use the widget&#39;s <code>getEventHandler</code> method to return the widget&#39;s handler name when you refer to it in the widget partials.</p><pre><code>&lt;a
    href=&quot;javascript:;&quot;
    data-request=&quot;&lt;?= $this-&gt;getEventHandler(&#39;onPaginate&#39;) ?&gt;&quot;
    title=&quot;Next page&quot;&gt;Next&lt;/a&gt;
</code></pre><p>When called from a widget class or partial the AJAX handler will target itself. For example, if the widget uses the alias of <strong>mywidget</strong> the handler will be targeted with <code>mywidget::onName</code>. The above would output the following attribute value:</p><pre><code>data-request=&quot;mywidget::onPaginate&quot;
</code></pre><h3 id="binding-widgets-to-controllers"><a href="#binding-widgets-to-controllers" class="header-anchor">#</a> Binding widgets to controllers</h3><p>A widget should be bound to a <a href="./controllers-ajax.html">back-end controller</a> before you can start using it in a back-end page or partial. Use the widget&#39;s <code>bindToController</code> method for binding it to a controller. The best place to initialize a widget is the controller&#39;s constructor. Example:</p><pre><code>public function __construct()
{
    parent::__construct();

    $myWidget = new MyWidgetClass($this);
    $myWidget-&gt;alias = &#39;myWidget&#39;;
    $myWidget-&gt;bindToController();
}
</code></pre><p>After binding the widget you can access it in the controller&#39;s view or partial by its alias:</p><pre><code>&lt;?= $this-&gt;widget-&gt;myWidget-&gt;render() ?&gt;
</code></pre><h2 id="form-widgets"><a href="#form-widgets" class="header-anchor">#</a> Form Widgets</h2><p>With form widgets you can add new control types to the back-end <a href="./../backend/forms.html">forms</a>. They provide features that are common to supplying data for models. Form widgets must be registered in the <a href="./../plugin/registration.html#registration-methods">Plugin registration file</a>.</p><p>Form Widget classes reside inside the <strong>formwidgets</strong> directory of the plugin directory. The directory name matches the name of the widget class written in lowercase. Widgets can supply assets and partials. An example form widget directory structure looks like this:</p><pre><code>formwidgets/
  /form
    /partials
      _form.htm     &lt;=== Widget partial file
    /assets
      /js
        form.js     &lt;=== Widget JavaScript file
      /css
        form.css    &lt;=== Widget StyleSheet file
  Form.php          &lt;=== Widget class
</code></pre><h3 id="class-definition-1"><a href="#class-definition-1" class="header-anchor">#</a> Class definition</h3><p>The form widget classes must extend the <code>Backend\\Classes\\FormWidgetBase</code> class. As any other plugin class, generic widget controllers should belong to the <a href="./../plugin/registration.html#plugin-namespaces">plugin namespace</a>. A registered widget can be used in the back-end <a href="./../backend/forms.html#defining-form-fields">form field definition</a> file. Example form widget class definition:</p><pre><code>namespace Backend\\Widgets;

use Backend\\Classes\\FormWidgetBase;

class CodeEditor extends FormWidgetBase
{
    /**
     * @var string A unique alias to identify this widget.
     */
    protected $defaultAlias = &#39;codeeditor&#39;;

    public function render() {}
}
</code></pre><h3 id="form-widget-properties"><a href="#form-widget-properties" class="header-anchor">#</a> Form widget properties</h3><p>Form widgets may have properties that can be set using the <a href="./../backend/forms.html#defining-form-fields">form field configuration</a>. Simply define the configurable properties on the class and then call the <code>fillFromConfig</code> method to populate them inside the <code>init</code> method definition.</p><pre><code>class DatePicker extends FormWidgetBase
{
    //
    // Configurable properties
    //

    /**
     * @var bool Display mode: datetime, date, time.
     */
    public $mode = &#39;datetime&#39;;

    /**
     * @var string the minimum/earliest date that can be selected.
     * eg: 2000-01-01
     */
    public $minDate = null;

    /**
     * @var string the maximum/latest date that can be selected.
     * eg: 2020-12-31
     */
    public $maxDate = null;

    //
    // Object properties
    //

    /**
     * {@inheritDoc}
     */
    protected $defaultAlias = &#39;datepicker&#39;;

    /**
     * {@inheritDoc}
     */
    public function init()
    {
        $this-&gt;fillFromConfig([
            &#39;mode&#39;,
            &#39;minDate&#39;,
            &#39;maxDate&#39;,
        ]);
    }

    // ...
}
</code></pre><p>The property values then become available to set from the <a href="./../backend/forms.html#defining-form-fields">form field definition</a> when using the widget.</p><pre><code>born_at:
    label: Date of Birth
    type: datepicker
    mode: date
    minDate: 1984-04-12
    maxDate: 2014-04-23
</code></pre><h3 id="form-widget-registration"><a href="#form-widget-registration" class="header-anchor">#</a> Form widget registration</h3><p>Plugins should register form widgets by overriding the <code>registerFormWidgets</code> method inside the <a href="./../plugin/registration.html#registration-file">Plugin registration class</a>. The method returns an array containing the widget class in the keys and widget short code as the value. Example:</p><pre><code>public function registerFormWidgets()
{
    return [
        &#39;Backend\\FormWidgets\\CodeEditor&#39; =&gt; &#39;codeeditor&#39;,
        &#39;Backend\\FormWidgets\\RichEditor&#39; =&gt; &#39;richeditor&#39;
    ];
}
</code></pre><p>The short code is optional and can be used when referencing the widget in the <a href="./forms.html#field-widget">Form field definitions</a>, it should be a unique value to avoid conflicts with other form fields.</p><h3 id="loading-form-data"><a href="#loading-form-data" class="header-anchor">#</a> Loading form data</h3><p>The main purpose of the form widget is to interact with your model, which means in most cases loading and saving the value via the database. When a form widget renders, it will request its stored value using the <code>getLoadValue</code> method. The <code>getId</code> and <code>getFieldName</code> methods will return a unique identifier and name for a HTML element used in the form. These values are often passed to the widget partial at render time.</p><pre><code>public function render()
{
    $this-&gt;vars[&#39;id&#39;] = $this-&gt;getId();
    $this-&gt;vars[&#39;name&#39;] = $this-&gt;getFieldName();
    $this-&gt;vars[&#39;value&#39;] = $this-&gt;getLoadValue();

    return $this-&gt;makePartial(&#39;myformwidget&#39;);
}
</code></pre><p>At a basic level the form widget can send the user input value back using an input element. From the above example, inside the <strong>myformwidget</strong> partial the element can be rendered using the prepared variables.</p><pre><code>&lt;input id=&quot;&lt;?= $id ?&gt;&quot; name=&quot;&lt;?= $name ?&gt;&quot; value=&quot;&lt;?= e($value) ?&gt;&quot; /&gt;
</code></pre><h3 id="saving-form-data"><a href="#saving-form-data" class="header-anchor">#</a> Saving form data</h3><p>When the time comes to take the user input and store it in the database, the form widget will call the <code>getSaveValue</code> internally to request the value. To modify this behavior simply override the method in your form widget class.</p><pre><code>public function getSaveValue($value)
{
    return $value;
}
</code></pre><p>In some cases you intentionally don&#39;t want any value to be given, for example, a form widget that displays information without saving anything. Return the special constant called <code>FormField::NO_SAVE_DATA</code> derived from the <code>Backend\\Classes\\FormField</code> class to have the value ignored.</p><pre><code>public function getSaveValue($value)
{
    return \\Backend\\Classes\\FormField::NO_SAVE_DATA;
}
</code></pre><h2 id="report-widgets"><a href="#report-widgets" class="header-anchor">#</a> Report Widgets</h2><p>Report widgets can be used on the back-end dashboard and in other back-end report containers. Report widgets must be registered in the <a href="./../plugin/registration.html#widget-registration">Plugin registration file</a>.</p><blockquote><p>You can easily scaffold a report widget using the <code>create:reportwidget</code> command. See <a href="./../console/scaffolding.html#create-a-report-widget">scaffolding commands</a> for more information.</p></blockquote><h3 id="report-widget-classes"><a href="#report-widget-classes" class="header-anchor">#</a> Report widget classes</h3><p>The report widget classes should extend the <code>Backend\\Classes\\ReportWidgetBase</code> class. As any other plugin class, generic widget controllers should belong to the <a href="./../plugin/registration.html#plugin-namespaces">plugin namespace</a>. The class should override the <code>render</code> method in order to render the widget itself. Similarly to all backend widgets, report widgets use partials and a special directory layout. Example directory layout:</p><pre><code>plugins/
  rainlab/                    &lt;=== Author name
    googleanalytics/          &lt;=== Plugin name
      reportwidgets/          &lt;=== Report widgets directory
        trafficsources        &lt;=== Widget files directory
          partials
            _widget.htm
        TrafficSources.php    &lt;=== Widget class file
</code></pre><p>Example report widget class definition:</p><pre><code>namespace RainLab\\GoogleAnalytics\\ReportWidgets;

use Backend\\Classes\\ReportWidgetBase;

class TrafficSources extends ReportWidgetBase
{
    public function render()
    {
        return $this-&gt;makePartial(&#39;widget&#39;);
    }
}
</code></pre><p>The widget partial could contain any HTML markup you want to display in the widget. The markup should be wrapped into the DIV element with the <strong>report-widget</strong> class. Using H3 element to output the widget header is preferable. Example widget partial:</p><pre><code>&lt;div class=&quot;report-widget&quot;&gt;
    &lt;h3&gt;Traffic sources&lt;/h3&gt;

    &lt;div
        class=&quot;control-chart&quot;
        data-control=&quot;chart-pie&quot;
        data-size=&quot;200&quot;
        data-center-text=&quot;180&quot;&gt;
        &lt;ul&gt;
            &lt;li&gt;Direct &lt;span&gt;1000&lt;/span&gt;&lt;/li&gt;
            &lt;li&gt;Social networks &lt;span&gt;800&lt;/span&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/div&gt;
&lt;/div&gt;
</code></pre><p><img src="https://raw.githubusercontent.com/octobercms/docs/master/images/traffic-sources.png" alt="image"></p><p>Inside report widgets you can use any <a href="./controls.html">charts or indicators</a>, lists or any other markup you wish. Remember that the report widgets extend the generic back-end widgets and you can use any widget functionality in your report widgets. The next example shows a list report widget markup.</p><pre><code>&lt;div class=&quot;report-widget&quot;&gt;
    &lt;h3&gt;Top pages&lt;/h3&gt;

    &lt;div class=&quot;table-container&quot;&gt;
        &lt;table class=&quot;table data&quot; data-provides=&quot;rowlink&quot;&gt;
            &lt;thead&gt;
                &lt;tr&gt;
                    &lt;th&gt;&lt;span&gt;Page URL&lt;/span&gt;&lt;/th&gt;
                    &lt;th&gt;&lt;span&gt;Pageviews&lt;/span&gt;&lt;/th&gt;
                    &lt;th&gt;&lt;span&gt;% Pageviews&lt;/span&gt;&lt;/th&gt;
                &lt;/tr&gt;
            &lt;/thead&gt;
            &lt;tbody&gt;
                &lt;tr&gt;
                    &lt;td&gt;/&lt;/td&gt;
                    &lt;td&gt;90&lt;/td&gt;
                    &lt;td&gt;
                        &lt;div class=&quot;progress&quot;&gt;
                            &lt;div class=&quot;bar&quot; style=&quot;90%&quot;&gt;&lt;/div&gt;
                            &lt;a href=&quot;/&quot;&gt;90%&lt;/a&gt;
                        &lt;/div&gt;
                    &lt;/td&gt;
                &lt;/tr&gt;
                &lt;tr&gt;
                    &lt;td&gt;/docs&lt;/td&gt;
                    &lt;td&gt;10&lt;/td&gt;
                    &lt;td&gt;
                        &lt;div class=&quot;progress&quot;&gt;
                            &lt;div class=&quot;bar&quot; style=&quot;10%&quot;&gt;&lt;/div&gt;
                            &lt;a href=&quot;/docs&quot;&gt;10%&lt;/a&gt;
                        &lt;/div&gt;
                    &lt;/td&gt;
                &lt;/tr&gt;
            &lt;/tbody&gt;
        &lt;/table&gt;
    &lt;/div&gt;
&lt;/div&gt;
</code></pre><h3 id="report-widget-properties"><a href="#report-widget-properties" class="header-anchor">#</a> Report widget properties</h3><p>Report widgets may have properties that users can manage with the Inspector:</p><p><img src="https://github.com/octobercms/docs/blob/develop/images/report-widget-inspector.png?raw=true" alt="image"></p><p>The properties should be defined in the <code>defineProperties</code> method of the widget class. The properties are described in the <a href="./../plugin/components.html#component-properties">components article</a>. Example:</p><pre><code>public function defineProperties()
{
    return [
        &#39;title&#39; =&gt; [
            &#39;title&#39;             =&gt; &#39;Widget title&#39;,
            &#39;default&#39;           =&gt; &#39;Top Pages&#39;,
            &#39;type&#39;              =&gt; &#39;string&#39;,
            &#39;validationPattern&#39; =&gt; &#39;^.+$&#39;,
            &#39;validationMessage&#39; =&gt; &#39;The Widget Title is required.&#39;
        ],
        &#39;days&#39; =&gt; [
            &#39;title&#39;             =&gt; &#39;Number of days to display data for&#39;,
            &#39;default&#39;           =&gt; &#39;7&#39;,
            &#39;type&#39;              =&gt; &#39;string&#39;,
            &#39;validationPattern&#39; =&gt; &#39;^[0-9]+$&#39;
        ]
    ];
}
</code></pre><h3 id="report-widget-registration"><a href="#report-widget-registration" class="header-anchor">#</a> Report widget registration</h3><p>Plugins can register report widgets by overriding the <code>registerReportWidgets</code> method inside the <a href="./../plugin/registration.html#registration-file">Plugin registration class</a>. The method should return an array containing the widget classes in the keys and widget configuration (label, context, and required permissions) in the values. Example:</p><pre><code>public function registerReportWidgets()
{
    return [
        &#39;RainLab\\GoogleAnalytics\\ReportWidgets\\TrafficOverview&#39; =&gt; [
            &#39;label&#39;   =&gt; &#39;Google Analytics traffic overview&#39;,
            &#39;context&#39; =&gt; &#39;dashboard&#39;,
            &#39;permissions&#39; =&gt; [
                &#39;rainlab.googleanalytics.widgets.traffic_overview&#39;,
            ],
        ],
        &#39;RainLab\\GoogleAnalytics\\ReportWidgets\\TrafficSources&#39; =&gt; [
            &#39;label&#39;   =&gt; &#39;Google Analytics traffic sources&#39;,
            &#39;context&#39; =&gt; &#39;dashboard&#39;,
            &#39;permissions&#39; =&gt; [
                &#39;rainlab.googleanaltyics.widgets.traffic_sources&#39;,
            ],
        ]
    ];
}
</code></pre><p>The <strong>label</strong> element defines the widget name for the Add Widget popup window. The <strong>context</strong> element defines the context where the widget could be used. October&#39;s report widget system allows to host the report container on any page, and the container context name is unique. The widget container on the Dashboard page uses the <strong>dashboard</strong> context.</p>`,72))])}const v=r(g,[["render",c]]);export{b as __pageData,v as default};
